-- 0026_maya_character_canonical_designs.sql
-- Generation-grade Canonical Design enrichments for 12 Maya launch characters.
PRAGMA foreign_keys = ON;

UPDATE characters SET canonical_design_json=json_patch(COALESCE(canonical_design_json,'{}'),'{"silhouette":"majestic feathered serpent forming a long flowing S-curve around temple architecture","appearance":{"face":["serpent head with elegant avian feather framing"],"body":["long limbless serpent body with coherent scale-and-feather transitions"]},"costumeLanguage":["no humanoid clothing; sacred quetzal-feather and carved-stone motifs only"],"paletteCues":["quetzal green","jade","sun gold"],"temperament":["majestic","ordered","windborne"],"mythologicalFacts":["Maya feathered-serpent deity strongly associated with Yucatán traditions"],"originalDesignChoices":["Keep serpent anatomy primary; architecture and feathers carry civilization identity."],"avoid":["East Asian dragon anatomy","winged European dragon","specific modern franchise likeness"],"canonicalPrompt":"Depict Kukulkan as an original MythCanvas Maya feathered-serpent deity. Preserve the long serpent body, quetzal feathers, wind and stepped-temple association. Keep anatomy limbless and serpent-first, using jade, carved stone and restrained sacred color rather than fantasy-dragon clichés."}') WHERE id='character-kukulkan';
UPDATE characters SET canonical_design_json=json_patch(COALESCE(canonical_design_json,'{}'),'{"silhouette":"elder creator-sage deity with tall headdress, writing implements and calm frontal posture","appearance":{"face":["aged dignified face with scholarly gaze"],"body":["lean mature adult proportions"]},"costumeLanguage":["Classic Maya-inspired elite ceremonial garments with jade beads, woven textiles and restrained headdress"],"paletteCues":["jade green","bone white","earth red"],"temperament":["wise","creative","ceremonial"],"mythologicalFacts":["important creator and knowledge deity in Maya traditions"],"originalDesignChoices":["Prioritize knowledge, writing and sky symbolism over generic wizard cues."],"avoid":["European wizard robes","generic tribal costume","specific modern franchise likeness"],"canonicalPrompt":"Depict Itzamna as an original MythCanvas Maya creator-sage. Preserve writing, sky and priestly knowledge motifs. Use Classic Maya-inspired ceremonial garments, jade and woven textiles with an elder, composed and scholarly divine presence."}') WHERE id='character-itzamna';
UPDATE characters SET canonical_design_json=json_patch(COALESCE(canonical_design_json,'{}'),'{"silhouette":"clearly adult moon goddess with crescent, weaving and flowing water vessel creating a graceful vertical composition","appearance":{"face":["clearly adult mature feminine face with calm healing gaze"],"body":["graceful adult proportions"]},"costumeLanguage":["Maya-inspired woven huipil-like ceremonial dress with jade, shell and lunar details"],"paletteCues":["moon white","jade","water blue"],"temperament":["healing","lunar","protective"],"mythologicalFacts":["deity associated in later Yucatán traditions with moon, childbirth, medicine and weaving"],"originalDesignChoices":["Use mature healer-weaver identity rather than generic moon-princess styling."],"avoid":["generic fantasy moon princess","youth-coded sexualization","specific modern franchise likeness"],"canonicalPrompt":"Depict Ix Chel as an original MythCanvas adult Maya moon-and-healing goddess. Preserve lunar, weaving and water-vessel motifs. Use refined Maya-inspired woven ceremonial garments with jade and shell, presenting a mature, protective healer rather than a generic fantasy moon princess."}') WHERE id='character-ix-chel';
UPDATE characters SET canonical_design_json=json_patch(COALESCE(canonical_design_json,'{}'),'{"silhouette":"powerful adult rain deity with long curling nose, rain axe and storm-cloud framing","appearance":{"face":["iconographic long-nosed rain-deity face with clear fangs and focused eyes"],"body":["strong adult humanoid proportions"]},"costumeLanguage":["Maya ceremonial regalia with jade, shell, woven bands and rain symbolism"],"paletteCues":["storm blue","jade","cloud white"],"temperament":["elemental","fertile","formidable"],"mythologicalFacts":["major Maya rain deity associated with storms and agriculture"],"originalDesignChoices":["Keep iconographic facial features readable without turning them into a monster mask."],"avoid":["generic demon mask","Aztec Tlaloc conflation","specific modern franchise likeness"],"canonicalPrompt":"Depict Chaac as an original MythCanvas Maya rain deity. Preserve the long curling nose, rain axe, lightning and agricultural storm identity. Use Maya ceremonial regalia and coherent iconographic facial features, keeping him divine rather than monstrous."}') WHERE id='character-chaac';
UPDATE characters SET canonical_design_json=json_patch(COALESCE(canonical_design_json,'{}'),'{"silhouette":"young-adult heroic ballplayer with blowgun and athletic forward motion","appearance":{"face":["clearly adult youthful face with focused intelligent gaze"],"body":["lean athletic adult build"]},"costumeLanguage":["Maya ballgame and hunter-warrior clothing with waist protection, woven bands and restrained ornaments"],"paletteCues":["sun gold","obsidian","maize tan"],"temperament":["clever","brave","playful"],"mythologicalFacts":["one of the Hero Twins in the Popol Vuh"],"originalDesignChoices":["Keep ballgame and blowgun identity primary; avoid superhero armor."],"avoid":["generic superhero suit","childlike proportions","specific modern franchise likeness"],"canonicalPrompt":"Depict Hunahpu as an original MythCanvas young-adult Maya Hero Twin. Preserve the blowgun, ballgame gear and solar heroic cues. Use Maya ballplayer-hunter garments and a lean, intelligent adult athletic presence."}') WHERE id='character-hunahpu';
UPDATE characters SET canonical_design_json=json_patch(COALESCE(canonical_design_json,'{}'),'{"silhouette":"young-adult heroic ballplayer with jaguar motif and agile low fighting stance","appearance":{"face":["clearly adult youthful face with alert determined gaze"],"body":["lean athletic adult build"]},"costumeLanguage":["Maya ballgame and hunter-warrior clothing with jaguar-pattern accents and woven protection"],"paletteCues":["jaguar black","moon silver","jade"],"temperament":["agile","clever","resolute"],"mythologicalFacts":["one of the Hero Twins in the Popol Vuh"],"originalDesignChoices":["Differentiate him from Hunahpu through jaguar and night cues, not a completely different cultural design."],"avoid":["generic ninja styling","childlike proportions","specific modern franchise likeness"],"canonicalPrompt":"Depict Xbalanque as an original MythCanvas young-adult Maya Hero Twin. Preserve the ballgame identity, jaguar associations and underworld-trial context. Use coherent Maya ballplayer-hunter garments with a lean, agile adult presence."}') WHERE id='character-xbalanque';
UPDATE characters SET canonical_design_json=json_patch(COALESCE(canonical_design_json,'{}'),'{"silhouette":"mature maize-associated hero with tall corn-leaf rhythm and ballgame regalia","appearance":{"face":["mature adult face with solemn regenerative expression"],"body":["lean mature adult proportions"]},"costumeLanguage":["Maya ballplayer and maize-ceremonial garments with woven bands and plant motifs"],"paletteCues":["maize gold","leaf green","earth red"],"temperament":["solemn","fertile","cyclical"],"mythologicalFacts":["father of the Hero Twins in the Popol Vuh, linked to ballgame and regeneration themes"],"originalDesignChoices":["Use maize regeneration symbolism carefully without asserting a single universal maize-god identity."],"avoid":["generic corn mascot","specific modern franchise likeness"],"canonicalPrompt":"Depict Hun Hunahpu as an original MythCanvas mature Maya mythic figure. Preserve ballgame, maize-regeneration and calabash-tree associations. Use Maya ceremonial-ballplayer garments and a solemn adult presence centered on death-and-return symbolism."}') WHERE id='character-hun-hunahpu';
UPDATE characters SET canonical_design_json=json_patch(COALESCE(canonical_design_json,'{}'),'{"silhouette":"large bat deity with folded membrane wings and blade-like snout silhouette","appearance":{"face":["naturalistic supernatural bat head with sharp ears and muzzle"],"body":["powerful bat-bodied or bat-humanoid form with coherent anatomy"]},"costumeLanguage":["minimal underworld regalia with obsidian and cave motifs"],"paletteCues":["cave black","obsidian","blood red accent"],"temperament":["predatory","nocturnal","ominous"],"mythologicalFacts":["bat-associated underworld being in the Popol Vuh Hero Twins narrative"],"originalDesignChoices":["Keep the design bat-first and underworld-specific; no vampire aristocrat clichés."],"avoid":["European vampire","gore fetish","specific modern franchise likeness"],"canonicalPrompt":"Depict Camazotz as an original MythCanvas Maya underworld bat deity. Preserve the bat anatomy, cave darkness and cutting-death motif. Use obsidian and underworld regalia sparingly, avoiding vampire, demon-wing or gore clichés."}') WHERE id='character-camazotz';
UPDATE characters SET canonical_design_json=json_patch(COALESCE(canonical_design_json,'{}'),'{"silhouette":"skeletal or death-marked adult underworld deity with rigid ritual posture","appearance":{"face":["death-marked skeletal face rendered iconographically rather than realistically gory"],"body":["lean adult humanoid body with funerary markings"]},"costumeLanguage":["Maya underworld ceremonial bands, bones and dark woven textiles"],"paletteCues":["bone white","soot black","earth red"],"temperament":["grim","ritual","chthonic"],"mythologicalFacts":["death deity name used in Maya traditions, especially Yucatán sources"],"originalDesignChoices":["Use archaeological-style death iconography without horror-zombie treatment."],"avoid":["gore","European grim reaper robe","specific modern franchise likeness"],"canonicalPrompt":"Depict Kisin as an original MythCanvas Maya death deity. Preserve skeletal death markings, underworld ritual context and dark ceremonial symbolism. Keep the figure iconographic and culturally grounded, avoiding gore, zombies or a European Grim Reaper silhouette."}') WHERE id='character-kisin';
UPDATE characters SET canonical_design_json=json_patch(COALESCE(canonical_design_json,'{}'),'{"silhouette":"powerful storm-creator presence centered on a single dynamic leg-like lightning spiral and cloud mass","appearance":{"face":["adult divine face emerging from storm with focused elemental gaze"],"body":["strong adult supernatural humanoid form"]},"costumeLanguage":["Maya ceremonial storm regalia with cloud, fire and lightning geometry"],"paletteCues":["storm grey","lightning white","fire amber"],"temperament":["creative","violent","elemental"],"mythologicalFacts":["Heart of Sky storm and creation deity in the Popol Vuh"],"originalDesignChoices":["Use spiral storm motion and sky-heart symbolism rather than modern hurricane iconography."],"avoid":["weather superhero","modern hurricane logo","specific modern franchise likeness"],"canonicalPrompt":"Depict Huracan as an original MythCanvas Maya storm-and-creation deity. Preserve Heart of Sky, whirlwind, lightning and fire motifs. Use Maya ceremonial storm language and a powerful adult elemental presence without modern weather-superhero styling."}') WHERE id='character-huracan';
UPDATE characters SET canonical_design_json=json_patch(COALESCE(canonical_design_json,'{}'),'{"silhouette":"enormous jeweled macaw with broad wings, extravagant beak and false-sun radiance","appearance":{"face":["large macaw head with jewel-like teeth and arrogant gaze"],"body":["massive naturalistic supernatural macaw body"]},"costumeLanguage":["no clothing; gemstone and celestial ornament integrated into feathers"],"paletteCues":["macaw red","sun gold","jade"],"temperament":["proud","dazzling","boastful"],"mythologicalFacts":["Vucub Caquix is the proud false sun figure defeated in the Popol Vuh"],"originalDesignChoices":["Keep him a supernatural macaw, not a humanoid bird king."],"avoid":["humanoid bird armor","generic phoenix","specific modern franchise likeness"],"canonicalPrompt":"Depict Vucub Caquix as an original MythCanvas supernatural macaw and false-sun figure. Preserve the giant macaw body, jewel-like teeth and dazzling false celestial radiance. Keep anatomy avian and culturally grounded, avoiding phoenix or armored bird-man clichés."}') WHERE id='character-vucub-caquix';
UPDATE characters SET canonical_design_json=json_patch(COALESCE(canonical_design_json,'{}'),'{"silhouette":"colossal earth-giant youth braced beneath mountain mass with broad grounded proportions","appearance":{"face":["adult or late-youth mythic face with proud stubborn gaze"],"body":["massive powerful humanoid body integrated visually with stone and earth"]},"costumeLanguage":["minimal Maya-inspired giant ornaments with stone, woven belts and earth motifs"],"paletteCues":["volcanic grey","maize tan","jade accent"],"temperament":["boastful","powerful","earthbound"],"mythologicalFacts":["earth-moving son of Vucub Caquix in the Popol Vuh"],"originalDesignChoices":["Scale comes from mountain relationship, not generic ogre anatomy."],"avoid":["generic fantasy ogre","rock golem","specific modern franchise likeness"],"canonicalPrompt":"Depict Zipacna as an original MythCanvas Maya earth-giant figure. Preserve his mountain-moving strength, earth and stone associations. Use restrained Maya-inspired ornaments and a massive humanoid form that feels tied to landscape rather than a generic ogre or rock golem."}') WHERE id='character-zipacna';
